INSERT INTO questions (id, module_id, sub_module_id, text, option_a, option_b, option_c, option_d, correct_answer, explanation, reference, difficulty) VALUES
('ang-095', 'anglais', 'ang-1', 'A client writes: “Please confirm the booking for tomorrow at 6 a.m.” What time is the ride?', 'Six o''clock in the morning', 'Six o''clock in the evening', 'At noon', 'At midnight', 'A', '“a.m.” means before midday (ante meridiem), so 6 a.m. is six in the morning. “p.m.” would mean six in the evening.', 'Module 6 – Anglais : vocabulaire professionnel', 'facile'::question_difficulty),
('topo-041', 'taxi-territoire', 'topo-axe', 'Un client doit rejoindre l''aéroport Charles-de-Gaulle depuis la porte de la Chapelle. Quel axe emprunter en priorité ?', 'L''autoroute A1', 'L''autoroute A6', 'L''autoroute A13', 'L''autoroute A4', 'A', 'L''A1, accessible porte de la Chapelle, dessert le nord de Paris et l''aéroport Roissy-Charles-de-Gaulle. L''A6 va vers Orly et Lyon, l''A13 vers la Normandie, l''A4 vers Reims.', 'Module 8 – Topographie : axes', 'facile'::question_difficulty),
('topo-042', 'taxi-territoire', 'topo-axe', 'Il est 18 h un vendredi. Un client part du 12e arrondissement vers Roissy-CDG. Le périphérique nord est saturé. Quelle solution est la plus pertinente ?', 'Sortir par l''est via l''A3 (porte de Bagnolet)', 'Emprunter l''A4 puis l''A86 pour rejoindre l''A1 par l''extérieur', 'Attendre que le périphérique se dégage', 'Traverser Paris par le centre pour rejoindre la porte de la Chapelle', 'A,B', 'Depuis l''est parisien, l''A3 offre un accès direct à CDG sans passer par le périphérique nord. Le contournement A4 + A86 est plus long en distance mais souvent plus rapide aux heures de pointe. Attendre ou traverser Paris fait perdre du temps.', 'Module 8 – Topographie : axes', 'difficile'::question_difficulty),
('topo-043', 'taxi-territoire', 'topo-gar', 'Un client vous dit : « Je prends le train pour Bordeaux dans une heure. » Vers quelle gare le conduisez-vous ?', 'Gare Montparnasse', 'Gare de Lyon', 'Gare de l''Est', 'Gare du Nord', 'A', 'Bordeaux est desservie par la gare Montparnasse (axe TGV Atlantique), comme Nantes, Rennes et Toulouse.', 'Module 8 – Topographie : gares', 'facile'::question_difficulty),
('topo-044', 'taxi-territoire', 'topo-gar', 'Un client veut aller à Deauville en train. Quelle gare et quelle particularité ?', 'Gare Saint-Lazare', 'Aucun TGV ne dessert cette destination', 'Gare Montparnasse', 'Gare d''Austerlitz', 'A,B', 'Deauville est en Normandie, desservie depuis Saint-Lazare. Cet axe n''est pas desservi par TGV mais par des trains Intercités ou régionaux — précision utile pour un client qui cherche « le TGV ».', 'Module 8 – Topographie : gares', 'moyen'::question_difficulty),
('topo-045', 'taxi-territoire', 'topo-mon', 'Un touriste demande à être déposé « à l''Étoile, près du grand arc ». Où le conduisez-vous et quelle précaution prenez-vous ?', 'Place Charles-de-Gaulle, en déposant sur une avenue adjacente', 'Place de la Concorde, devant l''obélisque', 'Directement sous l''Arc de Triomphe', 'Place de la Bastille', 'A', '« L''Étoile » et « place Charles-de-Gaulle » désignent le même lieu. L''accès direct à l''Arc étant interdit aux véhicules, la dépose se fait sur une avenue voisine, le monument étant accessible par le passage souterrain.', 'Module 8 – Topographie : monuments', 'moyen'::question_difficulty),
('topo-046', 'taxi-territoire', 'topo-axe', 'Quelle est la vitesse maximale autorisée sur le boulevard périphérique parisien ?', '50 km/h', '70 km/h', '80 km/h', '30 km/h', 'A', 'Depuis le 1er octobre 2024, la vitesse maximale sur le boulevard périphérique est abaissée à 50 km/h.', 'Module 8 – Topographie : axes', 'facile'::question_difficulty),
('topo-047', 'taxi-territoire', 'topo-hop', 'Un client monte avec un enfant de trois ans fiévreux et demande « l''hôpital le plus proche » depuis le 7e arrondissement. Que faites-vous ?', 'Le conduire à l''hôpital Necker-Enfants malades, référence pédiatrique', 'Appeler le 15 si l''état de l''enfant semble grave', 'Le conduire aux urgences adultes les plus proches', 'Refuser la course pour raison médicale', 'A,B', 'Un enfant se conduit dans un hôpital pédiatrique : Necker (15e) est la référence, très proche du 7e. En cas de doute sur la gravité, le 15 oriente vers l''établissement adapté.', 'Module 8 – Topographie : hôpitaux', 'moyen'::question_difficulty),
('topo-048', 'taxi-territoire', 'topo-hop', 'Quel est le plus grand hôpital de Paris, situé dans le 13e arrondissement ?', 'La Pitié-Salpêtrière', 'L''Hôtel-Dieu', 'L''hôpital Cochin', 'L''hôpital Bichat', 'A', 'La Pitié-Salpêtrière, boulevard de l''Hôpital dans le 13e, est le plus grand hôpital de France et l''un des plus grands d''Europe, toutes spécialités confondues.', 'Module 8 – Topographie : hôpitaux', 'facile'::question_difficulty),
('topo-049', 'taxi-territoire', 'topo-axe', 'Un client veut aller de l''Opéra à la Bastille. Quel itinéraire est le plus direct ?', 'Les Grands Boulevards puis le boulevard Beaumarchais', 'Le boulevard périphérique par l''est', 'L''avenue des Champs-Élysées', 'Le boulevard Saint-Germain', 'A', 'L''Opéra et la Bastille sont reliés par l''axe des Grands Boulevards prolongé par le boulevard Beaumarchais : environ 4 km en ligne quasi droite. Le périphérique serait un immense détour, les Champs-Élysées et Saint-Germain vont dans d''autres directions.', 'Module 8 – Topographie : axes', 'moyen'::question_difficulty),
('topo-050', 'taxi-territoire', 'topo-mon', 'Sur quelle rive de la Seine se trouvent respectivement le musée d''Orsay et le Centre Pompidou ?', 'Orsay rive gauche, Pompidou rive droite', 'Les deux rive gauche', 'Les deux rive droite', 'Orsay rive droite, Pompidou rive gauche', 'A', 'Le musée d''Orsay est quai Anatole-France, dans le 7e (rive gauche). Le Centre Pompidou est dans le 4e (rive droite).', 'Module 8 – Topographie : monuments', 'moyen'::question_difficulty),
('topo-051', 'taxi-territoire', 'topo-gar', 'Deux gares parisiennes sont distantes de seulement 300 mètres et sont souvent confondues. Lesquelles ?', 'La gare du Nord et la gare de l''Est', 'La gare de Lyon et la gare d''Austerlitz', 'Montparnasse et Saint-Lazare', 'La gare du Nord et Saint-Lazare', 'A', 'La gare du Nord et la gare de l''Est sont voisines dans le 10e arrondissement, reliées par la rue La Fayette. La confusion est fréquente, notamment chez les touristes.', 'Module 8 – Topographie : gares', 'moyen'::question_difficulty),
('topo-052', 'taxi-territoire', 'topo-axe', 'Que sont les « boulevards des Maréchaux » ?', 'Une ceinture de boulevards située juste à l''intérieur du périphérique', 'Les grands axes du centre de Paris', 'Une portion de l''autoroute A86', 'Les quais de la Seine', 'A', 'Les boulevards des Maréchaux forment une ceinture intérieure, juste à l''intérieur du périphérique, portant les noms de maréchaux d''Empire. Ils constituent l''alternative classique quand le périphérique est saturé.', 'Module 8 – Topographie : axes', 'moyen'::question_difficulty),
('topo-053', 'taxi-territoire', 'topo-mon', 'Un client demande à être conduit « au Trocadéro pour photographier la tour Eiffel ». Dans quel arrondissement le déposez-vous ?', 'Le 16e arrondissement', 'Le 7e arrondissement', 'Le 8e arrondissement', 'Le 15e arrondissement', 'A', 'La place du Trocadéro et le palais de Chaillot sont dans le 16e, sur la rive droite, face à la tour Eiffel qui se trouve elle dans le 7e, rive gauche.', 'Module 8 – Topographie : monuments', 'moyen'::question_difficulty),
('topo-054', 'taxi-territoire', 'topo-axe', 'Quelle est la particularité de la circulation sur la place Charles-de-Gaulle (Étoile) ?', 'La priorité à droite s''y applique : les véhicules entrants sont prioritaires', 'Les véhicules déjà engagés sur l''anneau sont prioritaires', 'La circulation s''y fait en sens inverse des aiguilles d''une montre uniquement pour les taxis', 'Elle est interdite aux véhicules de transport de personnes', 'A', 'L''Étoile est l''un des rares carrefours où la priorité à droite s''applique sans exception : celui qui entre sur la place est prioritaire sur celui qui y circule déjà.', 'Module 8 – Topographie : axes', 'difficile'::question_difficulty),
('topo-055', 'taxi-territoire', 'topo-gar', 'Un client doit rejoindre l''aéroport d''Orly depuis le 14e arrondissement. Quel axe est le plus adapté ?', 'L''autoroute A6 depuis la porte d''Orléans', 'L''autoroute A1 depuis la porte de la Chapelle', 'L''autoroute A13 depuis la porte d''Auteuil', 'L''autoroute A4 depuis la porte de Bercy', 'A', 'Orly se situe au sud de Paris : depuis le 14e, l''accès naturel est la porte d''Orléans puis l''A6. Les autres autoroutes desservent le nord, l''ouest et l''est.', 'Module 8 – Topographie : gares et aéroports', 'facile'::question_difficulty),
('topo-056', 'taxi-territoire', 'topo-mon', 'Où se situe le quartier de la Défense et quelle est sa particularité pour un conducteur ?', 'À l''ouest, hors de Paris (Hauts-de-Seine), dans le prolongement de l''axe historique', 'Dans le 16e arrondissement de Paris', 'Au sud de Paris, près d''Orly', 'C''est le nom du quartier des ministères dans le 7e', 'A', 'La Défense se situe hors de Paris, sur les communes de Puteaux, Courbevoie et Nanterre, dans le prolongement de l''axe Louvre – Concorde – Champs-Élysées – Arc de Triomphe.', 'Module 8 – Topographie : monuments', 'moyen'::question_difficulty),
('topo-057', 'taxi-territoire', 'topo-axe', 'Un client vous demande de le conduire de la gare de Lyon à la gare Montparnasse. Que devez-vous anticiper ?', 'Une traversée de Paris d''est en ouest, à prévoir largement avant un train', 'Un trajet de moins de cinq minutes', 'Un passage obligatoire par le périphérique nord', 'Une impossibilité : les deux gares ne sont pas reliées par la route', 'A', 'Les deux gares sont à environ 6 km l''une de l''autre, de part et d''autre de la Seine : la traversée demande 20 à 35 minutes selon le trafic. Il faut prévenir un client pressé.', 'Module 8 – Topographie : axes', 'moyen'::question_difficulty),
('topo-058', 'taxi-territoire', 'topo-hop', 'L''hôpital américain de Paris, souvent demandé par la clientèle internationale, se situe :', 'À Neuilly-sur-Seine, hors de Paris', 'Dans le 8e arrondissement', 'Dans le 16e arrondissement', 'À Saint-Denis', 'A', 'L''hôpital américain de Paris se trouve boulevard Victor-Hugo à Neuilly-sur-Seine (92), en limite ouest de Paris.', 'Module 8 – Topographie : hôpitaux', 'moyen'::question_difficulty),
('topo-059', 'taxi-territoire', 'topo-mon', 'La place de la République est connue des conducteurs parisiens pour une raison particulière. Laquelle ?', 'Elle est fréquemment bloquée par des manifestations', 'Elle est réservée aux véhicules électriques', 'Elle est entièrement piétonne depuis 2013', 'Elle est interdite aux taxis', 'A', 'La place de la République est le point de départ ou d''arrivée habituel des manifestations parisiennes : elle est régulièrement bloquée, ainsi que les boulevards adjacents.', 'Module 8 – Topographie : monuments et places', 'moyen'::question_difficulty),
('topo-060', 'taxi-territoire', 'topo-axe', 'Que doit vérifier un conducteur concernant la Zone à Faibles Émissions (ZFE) du Grand Paris ?', 'Que la vignette Crit''Air de son véhicule autorise la circulation dans le périmètre', 'Que son véhicule a moins de deux ans', 'Qu''il possède un badge de télépéage', 'Que son véhicule est immatriculé à Paris', 'A', 'La ZFE métropolitaine restreint la circulation selon le niveau de vignette Crit''Air. Ni l''âge exact, ni le télépéage, ni le lieu d''immatriculation n''entrent en jeu.', 'Module 8 – Topographie : circulation', 'moyen'::question_difficulty)
